export const baseStyles = ":host {\n  box-sizing: border-box;\n  color: var(--nala-ui-color-text, #18201d);\n  font-family: var(--nala-ui-font-body, \"Avenir Next\", \"Gill Sans\", sans-serif);\n}\n\n*, *::before, *::after {\n  box-sizing: border-box;\n}\n";
export const fieldStyles = `${baseStyles}\n${":host {\n  display: block;\n}\n\n.field {\n  display: grid;\n  gap: 0.4rem;\n}\n\n.label {\n  color: var(--nala-ui-color-text, #18201d);\n  font-size: 0.84rem;\n  font-weight: 750;\n}\n\n.hint {\n  color: var(--nala-ui-color-text-muted, #68716c);\n  font-size: 0.76rem;\n  line-height: 1.4;\n}\n\n.control {\n  width: 100%;\n  min-width: 0;\n  min-height: 2.75rem;\n  border: 1px solid var(--nala-ui-color-border, #cbcfc8);\n  border-radius: var(--nala-ui-radius-small, 4px);\n  outline: none;\n  background: var(--nala-ui-color-surface, #fffefa);\n  color: var(--nala-ui-color-text, #18201d);\n  font: inherit;\n}\n\n.control:focus-visible {\n  border-color: var(--nala-ui-color-accent, #184d3b);\n  box-shadow: 0 0 0 3px var(--nala-ui-color-accent-soft, #d8e8df);\n}\n\n.control:disabled {\n  cursor: not-allowed;\n  opacity: 0.55;\n}\n"}`;
